impl StrictModeVerification for SearchParams {
    async fn check_custom(
        &self,
        _collection: &Collection,
        strict_mode_config: &StrictModeConfig,
    ) -> CollectionResult<()> {
        check_limit_opt(
            self.quantization.and_then(|i| i.oversampling),
            strict_mode_config.search_max_oversampling,
            "oversampling",
        )?;

        check_limit_opt(
            self.hnsw_ef,
            strict_mode_config.search_max_hnsw_ef,
            "hnsw_ef",
        )?;

        check_limit_opt(
            self.score_threshold, // ❌ NO CHECK - just passes through
            strict_mode_config.search_max_score_threshold, // ❌ NOT USED
            "score_threshold",
        )?
